import * as THREE from 'three/webgpu';
import { color, mix, uv, float } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'orbit-product-hero';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];
  const disposables = [];

  // Backdrop plane with engineered gradient
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  disposables.push(backdropGeo);
  const gradColor = mix(
    mix(color('#0b0b10'), color('#101017'), uv().y.remap(0.0, 0.55, 0.0, 1.0).clamp(0, 1)),
    color('#16161d'),
    uv().y.remap(0.55, 1.0, 0.0, 1.0).clamp(0, 1)
  );
  const backdropMat = new THREE.MeshBasicNodeMaterial();
  backdropMat.colorNode = gradColor;
  disposables.push(backdropMat);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Plinth
  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 48);
  disposables.push(plinthGeo);
  const plinthMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  disposables.push(plinthMat);
  const plinth = new THREE.Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.1 - 0.125, 0);
  group.add(plinth);

  // Contact shadow
  const shadowGeo = new THREE.CircleGeometry(1.6, 48);
  disposables.push(shadowGeo);
  const shadowMat = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.55,
  });
  const shadowColor = mix(color('#000000'), color('#000000'), float(0));
  shadowMat.colorNode = shadowColor;
  const shadowAlpha = float(1.0).sub(uv().sub(0.5).length().mul(2.0)).clamp(0, 1).mul(0.55);
  shadowMat.opacityNode = shadowAlpha;
  disposables.push(shadowMat);
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.1 - 0.25 - 0.001, 0);
  group.add(shadow);

  // Watch mesh
  const watchGroup = new THREE.Group();
  watchGroup.name = 'watch-mesh-group';
  group.add(watchGroup);

  const gltf = ctx.glbLoader.load('/prism-mock/orrery/meshes/watch.glb');
  const applyWatch = (root) => {
    const box = new THREE.Box3().setFromObject(root);
    const size = new THREE.Vector3();
    box.getSize(size);
    const targetHeight = 2.2;
    const scaleFactor = size.y > 0 ? targetHeight / size.y : 1;
    root.scale.setScalar(scaleFactor);

    const box2 = new THREE.Box3().setFromObject(root);
    const center = new THREE.Vector3();
    box2.getCenter(center);
    root.position.sub(center);

    root.traverse((child) => {
      if (child.isMesh) {
        child.material = new THREE.MeshPhysicalNodeMaterial({
          color: child.material?.color ?? new THREE.Color('#cfd3d8'),
          map: child.material?.map ?? null,
          roughness: 0.52,
          metalness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.4,
        });
        child.material.anisotropy = 0.8;
        child.material.emissive = new THREE.Color('#ff2a38');
        child.material.emissiveIntensity = 0.0;
      }
    });

    watchGroup.add(root);

    // Rim light accent mesh - thin emissive ring on left flank
    const rimGeo = new THREE.TorusGeometry(0.55, 0.01, 8, 48, Math.PI * 0.5);
    disposables.push(rimGeo);
    const rimMat = new THREE.MeshBasicNodeMaterial({
      color: new THREE.Color('#ff2a38'),
    });
    rimMat.colorNode = color('#ff2a38').mul(1.6);
    disposables.push(rimMat);
    const rim = new THREE.Mesh(rimGeo, rimMat);
    rim.rotation.z = Math.PI * 0.75;
    rim.position.set(-0.3, 0, 0.1);
    watchGroup.add(rim);
  };

  if (gltf && gltf.scene) {
    applyWatch(gltf.scene);
  } else if (gltf && gltf.then) {
    gltf.then((res) => applyWatch(res.scene));
  }

  // Lighting: key + rim + accent
  const keyLight = new THREE.DirectionalLight('#e8ecf2', 1.2);
  keyLight.position.set(2, 3, 2);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight('#ffffff', 0.8);
  rimLight.position.set(-2.5, 1.5, -1.5);
  group.add(rimLight);

  const accentLight = new THREE.PointLight('#ff2a38', 1.6, 4, 2);
  accentLight.position.set(-1.2, 0.2, 0.8);
  group.add(accentLight);

  const ambient = new THREE.AmbientLight('#16161d', 0.3);
  group.add(ambient);

  // Text content
  const headlineMesh = createTextMesh({
    text: 'Calibre NA-01',
    font: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
    fontAtlas: ctx.fontAtlas,
  });
  headlineMesh.position.set(0, -1.5, 0);
  group.add(headlineMesh);

  const bodyMesh = createTextMesh({
    text: 'Machined in-house. 41 mm. Grade 5 titanium.',
    font: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: '#e8ecf2',
    fontAtlas: ctx.fontAtlas,
  });
  bodyMesh.position.set(0, -1.75, 0);
  group.add(bodyMesh);

  const captionMesh = createTextMesh({
    text: 'FROM 4200 USD / SHIPS IN 21 DAYS',
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#ff2a38',
    fontAtlas: ctx.fontAtlas,
  });
  captionMesh.position.set(0, -2.0, 0);
  group.add(captionMesh);

  // Apply cinematic primitives via ctx.primitives
  ctx.primitives['orbit'](watchGroup, { speed: 0.15, radius: 0.6 });
  ctx.primitives['depth-rotate'](watchGroup, { maxDeg: 6, trigger: 'hover' });

  // Hover / interaction handlers
  let hoverTl = null;

  const onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    timelines.push(hoverTl);
    hoverTl.to(watchGroup.scale, {
      x: 1.0, y: 1.0, z: 1.0,
      duration: 0.3,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    });
  };

  const onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    timelines.push(hoverTl);
    hoverTl.fromTo(
      watchGroup.scale,
      { x: 1.04, y: 1.04, z: 1.04 },
      { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }
    );
  };

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });
    watchGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      }
    });
    headlineMesh.geometry?.dispose?.();
    headlineMesh.material?.dispose?.();
    bodyMesh.geometry?.dispose?.();
    bodyMesh.material?.dispose?.();
    captionMesh.geometry?.dispose?.();
    captionMesh.material?.dispose?.();
  };

  return group;
}
